/* Backend simulado do Apps Script, só para ver a página funcionando. */
const http = require('http');
const fs = require('fs');
const path = require('path');

const RAIZ = 'C:/Atiz/encontro-pc-sistemas';
const LIMITE = 100;

const NOMES = ['Ana Prado','Bruno Lima','Carla Souza','Diego Rocha','Elis Matos','Fábio Nunes',
  'Gabi Ramos','Hugo Teles','Iara Melo','João Vieira','Kelly Braga','Léo Antunes',
  'Marina Costa','Nando Reis','Olívia Paz','Paulo Sá','Rita Alves','Sérgio Dias',
  'Tati Moura','Vitor Barros'];

let registros = [];
for (let i = 0; i < 40; i++) {                     // 40 titulares + 60 acompanhantes = 100 pessoas
  const extras = i < 20 ? 2 : 1;
  registros.push({
    telefone: '629' + String(10000000 + i),
    nome: NOMES[i % NOMES.length] + (i >= NOMES.length ? ' Jr.' : ''),
    pessoas: extras,
    acompanhantes: extras === 2 ? ['Duda'] : []
  });
}

let fila = [
  { telefone: '62991110001', nome: 'Renata Figueiredo' },
  { telefone: '62991110002', nome: 'Marcos Aurélio Tavares' },
  { telefone: '62991110003', nome: 'Juliana Prado' }
];

const capacidade = () => {
  const ocupadas = registros.reduce((s, r) => s + r.pessoas, 0);
  return { limite: LIMITE, ocupadas, vagas: Math.max(0, LIMITE - ocupadas), esgotado: ocupadas >= LIMITE };
};
const mural = () => registros.map(r => ({
  nome: r.nome, pessoas: r.pessoas, acompanhantes: r.acompanhantes,
  par: parseInt(r.telefone.slice(-1), 10) % 2
}));
const espera = () => fila.map((e, i) => ({
  nome: e.nome, posicao: i + 1, par: parseInt(e.telefone.slice(-1), 10) % 2
}));
const posicao = (tel) => {
  const i = fila.findIndex(e => e.telefone === tel);
  return i < 0 ? null : { posicao: i + 1, nome: fila[i].nome, total: fila.length };
};

http.createServer((req, res) => {
  if (req.url.startsWith('/api')) {
    let corpo = '';
    req.on('data', c => corpo += c);
    req.on('end', () => {
      const d = JSON.parse(corpo || '{}');
      let saida;
      if (d.acao === 'listar') {
        saida = { ok: true, mural: mural(), espera: espera(), capacidade: capacidade() };
      } else if (d.acao === 'consultar') {
        const r = registros.find(x => x.telefone === d.telefone);
        saida = { ok: true, registro: r ? { nome: r.nome, combo: 'feijoada', dependentes: [], recado: '' } : null,
                  naEspera: posicao(d.telefone), capacidade: capacidade() };
      } else if (d.acao === 'esperar') {
        if (posicao(d.telefone)) {
          saida = { ok: false, naEspera: posicao(d.telefone), erro: 'Já está na fila.',
                    capacidade: capacidade(), mural: mural(), espera: espera() };
        } else {
          fila.push({ telefone: d.telefone, nome: d.nome });
          saida = { ok: true, naEspera: posicao(d.telefone), capacidade: capacidade(),
                    mural: mural(), espera: espera() };
        }
      } else {
        saida = { ok: false, erro: 'ação simulada não implementada' };
      }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(saida));
    });
    return;
  }

  const html = fs.readFileSync(path.join(RAIZ, 'index.html'), 'utf8')
    .replace(/const API_URL\s*=\s*'[^']*'/, "const API_URL = '/api'");
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}).listen(4173, () => console.log('mock em http://localhost:4173'));
